<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';
type Capability = { supported?: boolean; connected?: boolean; available?: boolean; enabled?: boolean; devices?: string[]; detail?: string };
type Agent = { agentId:string; hostname:string; os:string; platform:string; username:string; workspace:string; version:string; capabilities?:{screenshot:Capability;cdp9222:Capability;powershell:Capability;bash:Capability;adb:Capability} };
type SchemaProperty = {type?:string;title?:string;description?:string;enum?:unknown[];default?:unknown;format?:string;items?:unknown;properties?:Record<string,unknown>};
type ToolDefinition = {name:string;description:string;inputSchema:{properties?:Record<string,SchemaProperty>;required?:string[]}};
const agents=ref<Agent[]>([]),selectedAgent=ref(''),loadingAgents=ref(false),totpLoading=ref(true),totp=ref<{configured?:boolean;account?:string;qrDataUrl?:string;error?:string}>();
const workspace=ref(''),workspaceLoading=ref(false),workspaceError=ref(''),tools=ref<ToolDefinition[]>([]),selectedTool=ref(''),fieldValues=reactive<Record<string,unknown>>({}),rawJsonMode=ref(false),argsText=ref('{}'),busy=ref(false),output=ref(''),outputError=ref(false),lastUpdated=ref('');
const connectedCount=computed(()=>agents.value.length),toolNames=computed(()=>tools.value.map(t=>t.name)),selectedDefinition=computed(()=>tools.value.find(t=>t.name===selectedTool.value)),schemaProperties=computed(()=>selectedDefinition.value?.inputSchema.properties??{}),requiredFields=computed(()=>selectedDefinition.value?.inputSchema.required??[]);
function defaultFor(p:SchemaProperty):unknown{if(p.default!==undefined)return p.default;if(p.enum?.length)return p.enum[0];if(p.type==='boolean')return false;if(p.type==='array')return '[]';if(p.type==='object')return '{}';return '';}
function resetFields(){for(const k of Object.keys(fieldValues))delete fieldValues[k];for(const [k,p] of Object.entries(schemaProperties.value)){if(k!=='agentId')fieldValues[k]=defaultFor(p);}fieldValues.intent=typeof fieldValues.intent==='string'&&fieldValues.intent?fieldValues.intent:'let me run this tool to perform the requested operation.';}
async function requestJson<T>(url:string,init?:RequestInit):Promise<T>{const r=await fetch(url,init);const body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(body.error||`${r.status} ${r.statusText}`);return body as T;}
async function loadTotp(){totpLoading.value=true;try{totp.value=await requestJson('/_admin/totp');}catch(e){totp.value={error:e instanceof Error?e.message:String(e)};}finally{totpLoading.value=false;}}
async function refreshAgents(){loadingAgents.value=true;try{const h=await requestJson<{agents:Agent[]}>('/_admin/agents');agents.value=h.agents;if(!agents.value.some(a=>a.agentId===selectedAgent.value))selectedAgent.value=agents.value[0]?.agentId??'';lastUpdated.value=new Date().toLocaleTimeString();}catch(e){outputError.value=true;output.value=`Unable to load gateway status: ${e instanceof Error?e.message:String(e)}`;}finally{loadingAgents.value=false;}}
async function loadTools(){try{const r=await requestJson<{tools:ToolDefinition[]}>('/_admin/tools');tools.value=r.tools;if(!tools.value.some(t=>t.name===selectedTool.value))selectedTool.value=tools.value[0]?.name??'';resetFields();}catch(e){outputError.value=true;output.value=String(e);}}
async function loadAgentWorkspace(){workspace.value='';workspaceError.value='';if(!selectedAgent.value)return;workspaceLoading.value=true;try{const r=await requestJson<{result:{workspace:string}}>('/_admin/call',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({tool:'get_system_info',args:{agentId:selectedAgent.value,intent:'let me inspect the agent workspace path for the admin console.'}})});workspace.value=r.result.workspace;}catch(e){workspaceError.value=e instanceof Error?e.message:String(e);}finally{workspaceLoading.value=false;}}
function buildArguments():Record<string,unknown>{const args:Record<string,unknown>={agentId:selectedAgent.value};for(const [key,p] of Object.entries(schemaProperties.value)){if(key==='agentId')continue;const value=fieldValues[key];if((p.type==='array'||p.type==='object')&&typeof value==='string'){try{args[key]=JSON.parse(value);}catch{throw new Error(`"${key}" must contain valid JSON`);}}else if(p.type==='integer'||p.type==='number'){if(value===''||value===undefined){if(requiredFields.value.includes(key))throw new Error(`"${key}" is required`);continue;}args[key]=Number(value);}else if(value!==''&&value!==undefined)args[key]=value;else if(requiredFields.value.includes(key))throw new Error(`"${key}" is required`);}return args;}
async function runTool(){if(!selectedAgent.value||!selectedTool.value)return;let args:Record<string,unknown>;try{if(rawJsonMode.value){const parsed=JSON.parse(argsText.value);if(!parsed||Array.isArray(parsed)||typeof parsed!=='object')throw new Error('Arguments must be a JSON object');args={...parsed,agentId:selectedAgent.value};}else args=buildArguments();}catch(e){outputError.value=true;output.value=`Invalid arguments: ${e instanceof Error?e.message:String(e)}`;return;}busy.value=true;output.value='';outputError.value=false;try{const r=await requestJson<{result:unknown}>('/_admin/call',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({tool:selectedTool.value,args})});output.value=JSON.stringify(r.result,null,2);}catch(e){outputError.value=true;output.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
watch(selectedAgent,()=>{void loadAgentWorkspace();});
watch(selectedTool,()=>resetFields());
onMounted(()=>{void loadTotp();void refreshAgents();void loadTools();});
</script>
<template><div class="shell">
<header class="topbar"><a class="brand" href="/"><span class="brand-mark">M</span><span>mcp<span class="brand-muted">/gateway</span></span></a><div class="topbar-right"><span class="live-dot"></span>LOCAL ADMIN CONSOLE<span class="version">HTTP</span></div></header>
<main><section class="hero"><div><div class="eyebrow">CONTROL PLANE <span>/</span> OVERVIEW</div><h1>Gateway console</h1><p>Connected agents, live capability probes and a schema-flexible tool runner.</p></div><button class="button button-quiet" :disabled="loadingAgents" @click="refreshAgents"><span :class="{spinning:loadingAgents}">↻</span> Refresh status</button></section>
<section class="stats-grid"><article class="stat-card"><div class="stat-label">CONNECTED AGENTS</div><div class="stat-value">{{connectedCount.toString().padStart(2,'0')}}</div><div class="stat-foot"><span class="live-dot"></span>{{connectedCount?'Agent connection active':'Waiting for connections'}}</div></article><article class="stat-card"><div class="stat-label">GATEWAY STATUS</div><div class="stat-value status-value"><span class="status-indicator"></span>Online</div><div class="stat-foot">HTTP service responding</div></article><article class="stat-card"><div class="stat-label">LAST STATUS CHECK</div><div class="stat-value time-value">{{lastUpdated||'—'}}</div><div class="stat-foot">Local server time</div></article></section>
<div class="content-grid"><div class="main-column"><section class="panel"><div class="panel-heading"><div><div class="eyebrow">CONNECTIONS</div><h2>Connected agents</h2></div><span class="count-pill">{{connectedCount}} connected</span></div><div v-if="!agents.length" class="empty-state">No agents connected</div><div v-for="agent in agents" :key="agent.agentId" class="agent-card"><div class="agent-row"><span class="agent-avatar">⌘</span><div class="agent-details"><strong>{{agent.hostname}} · {{agent.agentId}}</strong><span>{{agent.os}} · {{agent.username}} · v{{agent.version}}</span></div><span class="agent-status"><i></i> Online</span></div><div class="capability-grid"><div class="capability"><span>截屏</span><b :class="agent.capabilities?.screenshot.supported?'good':'bad'">{{agent.capabilities?.screenshot.supported?'支持':'不支持'}}</b></div><div class="capability"><span>CDP 9222</span><b :class="agent.capabilities?.cdp9222.connected?'good':'bad'">{{agent.capabilities?.cdp9222.connected?'已连接':'未连接'}}</b></div><div class="capability"><span>PowerShell</span><b :class="agent.capabilities?.powershell.enabled?'good':'bad'">{{agent.capabilities?.powershell.available?(agent.capabilities.powershell.enabled?'可执行':'策略禁用'):'不可用'}}</b></div><div class="capability"><span>Bash</span><b :class="agent.capabilities?.bash.enabled?'good':'bad'">{{agent.capabilities?.bash.available?(agent.capabilities.bash.enabled?'可执行':'策略禁用'):'不可用'}}</b></div><div class="capability"><span>ADB</span><b :class="agent.capabilities?.adb.connected?'good':'bad'">{{agent.capabilities?.adb.connected?'已连接':'未连接'}}</b></div></div><div v-if="agent.capabilities?.adb.devices?.length" class="device-list">ADB devices: {{agent.capabilities.adb.devices.join(', ')}}</div></div></section>
<section class="panel actions-panel"><div class="panel-heading"><div><div class="eyebrow">REMOTE OPERATIONS</div><h2>Universal tool runner</h2></div><span class="subtle-tag">{{toolNames.length}} tools</span></div><p class="panel-description">从服务端工具清单中选择任意 Agent 工具。参数使用 JSON 输入，不再为每个工具单独编写表单；新增工具进入清单后即可调用。</p><label class="field-label" for="agent-select">TARGET AGENT</label><select id="agent-select" v-model="selectedAgent" class="field"><option v-for="agent in agents" :key="agent.agentId" :value="agent.agentId">{{agent.hostname}} ({{agent.agentId}})</option></select><div class="workspace-hint"><span class="field-label">AGENT WORKSPACE</span><span v-if="workspaceLoading" class="workspace-value">Loading…</span><span v-else class="workspace-value">{{workspace||workspaceError||'Select an agent'}}</span></div><label class="field-label spaced-label" for="tool-select">TOOL · {{toolNames.length}} AVAILABLE</label><select id="tool-select" v-model="selectedTool" class="field"><option v-for="tool in tools" :key="tool.name" :value="tool.name">{{tool.name}}</option></select><p v-if="selectedDefinition?.description" class="schema-description">{{selectedDefinition.description}}</p><div class="schema-toolbar"><span class="field-label">ARGUMENTS · GENERATED FROM JSON SCHEMA</span><button type="button" class="text-button" @click="rawJsonMode=!rawJsonMode">{{rawJsonMode?'Show generated form':'Edit raw JSON'}}</button></div><div v-if="!rawJsonMode" class="schema-form"><div v-for="(property,key) in schemaProperties" :key="key" v-show="key!=='agentId'" class="schema-field"><label class="field-label" :for="'arg-'+key">{{property.title||key}} <span v-if="requiredFields.includes(key)" class="required-mark">*</span><small class="type-hint">{{property.type||'value'}}</small></label><p v-if="property.description" class="schema-help">{{property.description}}</p><select v-if="property.enum?.length" :id="'arg-'+key" v-model="fieldValues[key]" class="field"><option v-for="option in property.enum" :key="String(option)" :value="option">{{option}}</option></select><label v-else-if="property.type==='boolean'" class="boolean-field"><input :id="'arg-'+key" v-model="fieldValues[key]" type="checkbox"/> <span>{{fieldValues[key]?'Enabled':'Disabled'}}</span></label><textarea v-else-if="property.type==='array'||property.type==='object'||property.format==='textarea'||['command','content','oldText','newText','patch'].includes(String(key))" :id="'arg-'+key" v-model="fieldValues[key]" class="field json-editor" rows="4" :placeholder="property.type==='array'?'[]':property.type==='object'?'{}':'Enter '+key"></textarea><input v-else :id="'arg-'+key" v-model="fieldValues[key]" class="field" :type="property.type==='integer'||property.type==='number'?'number':'text'" :placeholder="property.default!==undefined?String(property.default):'Enter '+key"/><span v-if="property.type==='array'||property.type==='object'" class="schema-help">请输入合法 JSON {{property.type==='array'?'数组':'对象'}}</span></div></div><textarea v-else v-model="argsText" class="field json-editor raw-json" rows="12" spellcheck="false" placeholder='{"path":"."}'></textarea><div class="form-actions"><button class="button button-secondary" :disabled="!selectedAgent||!selectedTool||busy" @click="runTool">{{busy?'Executing…':'Run tool'}}</button></div></section></div>
<aside class="side-column"><section v-if="output" class="panel result-panel"><div class="panel-heading"><div><div class="eyebrow">EXECUTION</div><h2>Latest result</h2></div><button class="text-button" @click="output=''">Clear</button></div><pre :class="{'result-error':outputError}">{{output}}</pre></section><section class="panel security-panel"><div class="panel-heading"><div><div class="eyebrow">ACCOUNT SECURITY</div><h2>Authenticator</h2></div><span class="shield">◆</span></div><p class="panel-description">Scan this QR code with a TOTP app. This setup is only available from the local admin page.</p><div class="qr-wrap"><div v-if="totpLoading" class="qr-placeholder">Loading secure setup…</div><img v-else-if="totp?.qrDataUrl" :src="totp.qrDataUrl" alt="Authenticator setup QR code"/><div v-else class="qr-placeholder error-text">{{totp?.error||'Unable to load authenticator setup.'}}</div></div><div v-if="totp?.configured" class="configured-note"><span class="live-dot"></span><div><strong>Authenticator configured</strong><small>Account · {{totp.account}}</small></div></div></section><section class="info-card"><div class="info-icon">i</div><div><strong>Local access only</strong><p>仅允许本机直连。工具调用仍受 Agent 自身权限策略和工作区限制约束。</p></div></section></aside></div><footer>CHATGPT MCP GATEWAY <span>·</span> LOCAL ADMINISTRATION</footer></main></div></template>
